// Seite mit neuem Schlüssel ausliefern; Schlüssel gilt 8 Stunden für Start und Stand (25.10.2026)
const SEITE = "<!doctype html>
<html lang="de">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>BC3 · Live-Demo</title>
<!-- 25.10.2026: Demo-Seite. Die Erklärung klappt am laufenden Schritt auf, die Seite folgt ihm; nach Gate 2 zeigt sie
     die Entscheidung und die Übergabe (BC3-80). Start und Stand prüfen den Schlüssel, den n8n beim Ausliefern einsetzt.
     Lokal ohne n8n: ?probe=gut (Probelauf mit Entscheidung), ?probe=fehler (Fehlstart), ?tempo=4 (schneller). -->
<style>
:root { --flaeche:#F4F6F9; --karte:#FFFFFF; --dunkel:#1F3A5F; --text:#1F2933; --gedaempft:#6B7280; --linie:#E2E7EE;
  --akzent:#E39A2D; --akzent-text:#B26E0E; --ki:#4F7FB8; --ok:#2E9E5B; --live:#D64545; --nein:#B3412F;
  --sans:"Inter", system-ui, sans-serif; --mono:"JetBrains Mono", ui-monospace, Consolas, monospace; }
* { box-sizing:border-box; }
html { scroll-behavior:smooth; }
body { margin:0; background:var(--flaeche); color:var(--text); font:17px/1.5 var(--sans); }
header { background:var(--dunkel); color:#fff; padding:20px 40px; display:flex; align-items:center; gap:24px; }
header h1 { margin:0; font-size:26px; font-weight:650; }
header .art { margin-left:auto; font:600 14px var(--mono); letter-spacing:.1em; text-transform:uppercase; padding:6px 12px; border-radius:6px; border:2px solid #ffffff66; white-space:nowrap; }
header .art.live { background:var(--live); border-color:var(--live); } header .art.live::before { content:"● "; }
header .art.aufz { color:#C9D5E4; }
main { max-width:1180px; margin:0 auto; padding:28px 40px 80px; display:grid; grid-template-columns:1fr 340px; gap:28px; align-items:start; }
section { background:var(--karte); border:1px solid var(--linie); border-radius:14px; padding:22px 26px; }
h2 { font-size:15px; letter-spacing:.08em; text-transform:uppercase; color:var(--gedaempft); margin:0 0 14px; font-weight:600; }
.voll { grid-column:1 / -1; }
.vorher { display:grid; grid-template-columns:1fr 1fr; gap:28px; }
.vorher ol { margin:0; padding-left:22px; } .vorher li { margin:4px 0; }
.vorher .nachher li::marker { color:var(--ok); }
.start { display:flex; align-items:center; gap:16px; flex-wrap:wrap; }
button { font:inherit; cursor:pointer; }
.knopf { font-weight:700; font-size:18px; padding:14px 28px; border-radius:10px; border:0; background:var(--akzent); color:var(--dunkel); }
.knopf.zweit { background:transparent; border:2px solid var(--dunkel); color:var(--dunkel); font-size:16px; padding:11px 20px; }
.knopf[disabled] { opacity:.45; cursor:default; }
.start .hinweis { flex:1; min-width:260px; color:var(--gedaempft); font-size:15px; }
.fehler { display:none; flex-basis:100%; background:#FDECEC; border:2px solid var(--live); color:#8E1F1F; border-radius:10px; padding:14px 18px; font-weight:600; }
.fehler.an { display:block; } .fehler.info { background:#EEF3F9; border-color:var(--ki); color:var(--dunkel); } .fehler small { display:block; font-weight:400; margin-top:4px; }

/* Stationen: die laufende klappt auf und zeigt, was passiert */
.stationen { list-style:none; margin:0; padding:0; }
.st { border-top:1px solid var(--linie); padding:12px 12px; margin:0 -12px; border-radius:10px; scroll-margin:120px; }
.st:first-child { border-top:0; }
.st .zeile { display:grid; grid-template-columns:86px 1fr auto; gap:16px; align-items:baseline; }
.st.klickbar .zeile { cursor:pointer; }
.st .nr { font:600 15px var(--mono); color:var(--gedaempft); }
.st .name { font-weight:600; }
.st .marke { font:600 12px var(--mono); padding:2px 7px; border-radius:5px; margin-left:8px; vertical-align:2px; }
.st[data-art="ki"] .marke { color:var(--ki); border:1.5px solid var(--ki); }
.st[data-art="ratgeber"] .marke { color:var(--gedaempft); border:1.5px dashed var(--gedaempft); }
.st[data-art="mensch"] .marke { color:var(--akzent-text); border:1.5px solid var(--akzent); }
.st .rechts { font:14px var(--mono); color:var(--gedaempft); text-align:right; white-space:nowrap; }
.st .erg { grid-column:2 / 4; font-size:15px; color:var(--gedaempft); display:none; }
.st.fertig .erg { display:block; }
.st .balken { height:8px; border-radius:4px; background:var(--linie); overflow:hidden; margin:8px 0 0 102px; }
.st .balken i { display:block; height:100%; width:0; background:var(--dunkel); transition:width .3s linear; }
.st[data-art="ki"] .balken i { background:var(--ki); }
.st.fertig .nr::after { content:" ✓"; color:var(--ok); }
.st.fertig .balken i { width:100% !important; background:var(--ok); }
.st.nein .nr::after { content:" ✕"; color:var(--nein); }
.st.nein .balken i { width:100% !important; background:var(--nein); }
.st.aus { opacity:.45; }
.st.aktiv, .st.offen { background:#F4F8FD; }
.st.wartet { background:#FFF7EA; }
.st.wartet .balken i { width:100% !important; background:var(--akzent); animation:puls 1.4s ease-in-out infinite; }
@keyframes puls { 50% { opacity:.4; } }
.st .mehr { display:none; margin:12px 0 4px 102px; }
.st.offen .mehr { display:block; }
.st .satz { font-size:19px; line-height:1.45; margin:0; }
.st .zu { font-size:13px; background:none; border:0; color:var(--ki); padding:0; margin-top:8px; text-decoration:underline; }
.beispiel { margin-top:14px; border:1.5px dashed #C7D2E0; border-radius:12px; padding:14px 16px; background:#fff; }
.beispiel .kopf { font:600 12px var(--mono); letter-spacing:.06em; text-transform:uppercase; color:var(--akzent-text); }
.beispiel .titel { font-weight:650; margin:6px 0 8px; }
.beispiel .ak { font:14px/1.5 var(--mono); } .beispiel .ak b { color:var(--akzent-text); }
.beispiel .fuss { font-size:13px; color:var(--gedaempft); margin-top:8px; }
.beispiel .ampel { display:flex; gap:10px; align-items:center; margin:8px 0; }
.beispiel .ampel i { width:18px; height:18px; border-radius:50%; background:var(--ok); }
.beispiel .pflicht { font-size:15px; padding:6px 0; border-top:1px solid var(--linie); }
.beispiel .pflicht .tag { font:600 13px var(--mono); color:var(--dunkel); margin-right:6px; }
.beispiel .pflicht .an { display:block; font:13px var(--mono); color:var(--ki); } .beispiel .pflicht .an.org { color:var(--akzent-text); }
.tipp { font-size:14px; color:var(--gedaempft); margin-top:12px; }
/* Workflow-Aufbau und Links (25.10.2026) */
.links { display:flex; gap:16px; flex-wrap:wrap; margin-top:12px; font-size:14px; }
.links a { color:var(--ki); }
.aufbau { margin-top:16px; border-top:1px solid var(--linie); padding-top:12px; }
.aufbau .kopf { font:600 12px var(--mono); letter-spacing:.06em; text-transform:uppercase; color:var(--gedaempft); margin-bottom:8px; }
.aufbau ol { list-style:none; margin:0; padding:0; counter-reset:b; }
.aufbau li { position:relative; padding:6px 0 6px 34px; font-size:15px; line-height:1.4; }
.aufbau li::before { counter-increment:b; content:counter(b); position:absolute; left:0; top:7px; width:22px; height:22px; border-radius:50%;
  background:var(--linie); color:var(--dunkel); font:600 12px/22px var(--mono); text-align:center; }
.aufbau li:not(:last-child)::after { content:""; position:absolute; left:10px; top:30px; bottom:-6px; width:2px; background:var(--linie); }
.aufbau li b { font-weight:650; }
.aufbau li .art { font:600 11px var(--mono); padding:1px 6px; border-radius:4px; margin-left:6px; color:var(--gedaempft); border:1px solid var(--linie); }
.aufbau li.ki::before { background:var(--ki); color:#fff; } .aufbau li.ki .art { color:var(--ki); border-color:var(--ki); }
.aufbau li.weiche::before { content:"?"; background:#fff; border:2px solid var(--gedaempft); line-height:18px; }
.aufbau .neben { margin:2px 0 4px 34px; padding:6px 0 2px 14px; border-left:3px dashed #C7D2E0; }
.aufbau .neben .titel { font:600 12px var(--mono); color:var(--gedaempft); }
.aufbau .neben li::before { counter-increment:none; content:"↳"; background:none; font-size:15px; }
.aufbau .neben li::after { display:none; }

/* Rechts: bleibt beim Scrollen stehen */
/* Lauf und Stand-Kasten in einem eigenen Bereich: der Kasten läuft nur neben dem Lauf mit, nicht über die Abschnitte darunter */
.laufbereich { display:grid; grid-template-columns:1fr 340px; gap:28px; align-items:start; }
.stand { position:sticky; top:16px; }
.stand .uhr { font:600 46px/1 var(--mono); font-variant-numeric:tabular-nums; }
.stand .unter { font-size:14px; color:var(--gedaempft); margin:6px 0 16px; }
.stand .zahlen { display:flex; gap:22px; margin:6px 0 14px; }
.stand .zahlen div { font-size:14px; color:var(--gedaempft); } .stand .zahlen b { display:block; font:650 28px var(--sans); color:var(--dunkel); }
.entscheidung { display:none; border-radius:10px; padding:12px 14px; margin:10px 0 14px; font-size:15px; }
.entscheidung.an { display:block; }
.entscheidung b { display:block; font-size:18px; }
.entscheidung.ja { background:#EAF6EF; border:2px solid var(--ok); } .entscheidung.ja b { color:var(--ok); }
.entscheidung.nein { background:#FBEDEA; border:2px solid var(--nein); } .entscheidung.nein b { color:var(--nein); }
.entscheidung.nach { background:#FFF4E2; border:2px solid var(--akzent); } .entscheidung.nach b { color:var(--akzent-text); }
.stand a.gate { display:block; text-align:center; font:700 16px var(--sans); padding:12px 16px; border-radius:10px; background:var(--akzent); color:var(--dunkel); text-decoration:none; margin-top:8px; }
.stand a.gate[aria-disabled="true"] { opacity:.4; pointer-events:none; }
.stand .vergleich, .stand .grenze { font-size:13px; color:var(--gedaempft); margin-top:12px; }
/* Wo die Daten liegen (25.10.2026) */
.orte { display:grid; grid-template-columns:repeat(4, 1fr); gap:16px; }
.orte > div { border:1px solid var(--linie); border-radius:10px; padding:12px 14px; }
.orte b { display:block; color:var(--dunkel); } .orte span { display:block; font-size:13px; color:var(--gedaempft); margin-bottom:6px; }
.orte ul { margin:0; padding-left:18px; font-size:14px; } .orte li { margin:3px 0; }
.orte code { font:13px var(--mono); }
.orte .ort-link { display:inline-block; font-size:13px; color:var(--ki); margin:0 10px 8px 0; }
@media (max-width:900px) { .orte { grid-template-columns:1fr 1fr; } }
/* Ergebnis aus diesem Lauf (statt Beispiel), Vergleich, Begriffe, Druck (25.10.2026) */
.echt { display:none; margin-top:14px; border:2px solid var(--ok); border-radius:12px; padding:14px 16px; background:#fff; }
.echt.an { display:block; } .st .mehr:has(.echt.an) .beispiel { display:none; }
.echt .kopf { font:600 12px var(--mono); letter-spacing:.06em; text-transform:uppercase; color:var(--ok); }
.echt ul { margin:6px 0 0; padding-left:18px; } .echt li { margin:3px 0; font-size:15px; }
.echt .ak { font:14px/1.5 var(--mono); margin-top:8px; } .echt .fuss { font-size:13px; color:var(--gedaempft); margin-top:6px; }
.echt .ampel { display:flex; gap:10px; align-items:center; margin:6px 0; } .echt .ampel i { width:18px; height:18px; border-radius:50%; }
.vergleiche { display:none; } .vergleiche.an { display:block; }
.vergleiche .erkl { font-size:15px; color:var(--gedaempft); margin:0 0 12px; }
.vergleiche table { width:100%; border-collapse:collapse; font-size:15px; }
.vergleiche th { text-align:left; font:600 13px var(--mono); color:var(--gedaempft); padding:6px 8px; border-bottom:2px solid var(--linie); }
.vergleiche td { padding:7px 8px; border-bottom:1px solid var(--linie); font-variant-numeric:tabular-nums; }
.vergleiche tr.dieser td { background:#F4F8FD; font-weight:650; }
.vergleiche .punkt { display:inline-block; width:12px; height:12px; border-radius:50%; margin-right:6px; vertical-align:-1px; }
.begriff { border-bottom:1.5px dotted var(--ki); cursor:help; position:relative; }
.begriff:hover::after, .begriff:focus::after { content:attr(data-erkl); position:absolute; left:0; top:calc(100% + 6px); z-index:20; width:280px;
  background:var(--dunkel); color:#fff; font:400 14px/1.45 var(--sans); padding:10px 12px; border-radius:8px; box-shadow:0 8px 24px #0003; white-space:normal; }
.stand .pdf { display:none; width:100%; margin-top:14px; }
.stand .pdf.an { display:block; }
.druckkopf { display:none; }
@media print {
  body { background:#fff; font-size:12pt; }
  header, .start, .vorher, .tipp, .zu, .stand .gate, .stand .pdf, .links, .aufbau { display:none !important; }
  main { display:block; padding:0; max-width:none; }
  section { border:0; padding:0 0 10pt; }
  .stand { position:static; } .stand section { border-top:1px solid #ccc; padding-top:8pt; }
  .st { break-inside:avoid; background:none !important; } .st .mehr { display:block !important; } .st .balken { display:none; }
  .beispiel { display:none !important; } .echt { border-width:1px; }
  .begriff { border:0; } .begriff::after { display:none !important; }
  .druckkopf { display:block; font:11pt var(--sans); margin-bottom:10pt; border-bottom:2px solid #1F3A5F; padding-bottom:6pt; }
  .vergleiche.an { break-before:auto; }
}
@media (max-width:900px) { main, .laufbereich { grid-template-columns:1fr; } main { padding:20px 16px; } .vorher { grid-template-columns:1fr; } .stand { position:static; }
  .st .balken, .st .mehr { margin-left:0; } }
</style>
</head>
<body>
<header>
  <h1>BC3 · Vom Konzept zu Tickets, live</h1>
  <span class="art" id="art">bereit</span>
</header>
<main>
  <section class="voll vorher">
    <div>
      <h2>Ohne BC3</h2>
      <ol>
        <li>BC2 liefert ein Konzept: Text mit Potenzialen.</li>
        <li>Jemand liest es und schreibt von Hand Epics und User Stories.</li>
        <li>Jemand prüft von Hand KI-Verordnung und DSGVO.</li>
        <li>BC4 bekommt, was am Ende dabei herauskommt.</li>
      </ol>
    </div>
    <div class="nachher">
      <h2>Mit BC3</h2>
      <ol>
        <li>BC3 holt das freigegebene Konzept selbst.</li>
        <li>Feste Regeln und zwei KI-Schritte machen daraus Tickets mit rechtlicher Einordnung.</li>
        <li>Ein Mensch entscheidet an Gate 2.</li>
        <li>Erst dann geht die Lieferung an BC4.</li>
      </ol>
    </div>
  </section>

  <section class="voll start">
    <button type="button" class="knopf" id="pruefen">Jetzt prüfen</button>
    <button type="button" class="knopf zweit" id="los">Testfall</button>
    <button type="button" class="knopf zweit" id="aufz">Aufzeichnung ansehen</button>
    <div class="hinweis" id="hinweis"><b>Jetzt prüfen</b> holt eine neue Lieferung von BC2 und bearbeitet sie echt. <b>Testfall</b> läuft mit einem erfundenen Beispiel, nichts geht an BC4. Bis Gate 2 etwa anderthalb Minuten.</div>
    <div class="fehler" id="fehler"></div>
  </section>

  <div class="voll laufbereich">
  <section>
    <h2>Der Lauf, Schritt für Schritt</h2>
    <ul class="stationen" id="stationen"></ul>
    <div class="tipp">Der laufende Schritt klappt auf. Fertige Schritte lassen sich anklicken und wieder aufklappen.</div>
  </section>

  <aside class="stand">
    <section>
      <h2>Stand</h2>
      <div class="uhr" id="uhr">0:00</div>
      <div class="unter" id="uhr-unter">seit dem Start</div>
      <div class="zahlen"><div><b id="z-epics">–</b>Epics</div><div><b id="z-stories">–</b>Stories</div></div>
      <div class="entscheidung" id="entscheidung"></div>
      <a class="gate" id="gate" href="#" target="_blank" rel="noopener" aria-disabled="true">Gate-2-Seite öffnen</a>
      <div class="vergleich" id="vergleich"></div>
      <div class="grenze" id="grenze">Testlauf: Auch nach einer Freigabe entsteht kein Pull Request an BC4.</div>
      <button type="button" class="knopf zweit pdf" id="pdf">Als PDF speichern</button>
    </section>
  </aside>
  </div>

  <section class="voll daten">
    <h2>Wo die Daten liegen</h2>
    <div class="orte">
      <div><b>BC3-Datenbank</b><span>eigene Datenbank von BC3 (Supabase)</span><a class="ort-link" href="https://supabase.com/dashboard/projects" target="_blank" rel="noopener">Supabase öffnen ↗</a><ul><li><code>laeufe</code>: Stand jedes Laufs, davon lebt diese Seite</li><li><code>gate2_ansicht</code>: Daten der Gate-2-Seite</li><li><code>freigaben</code>: jede Entscheidung an Gate 2</li><li><code>fehler</code>: Abbrüche mit Einordnung</li></ul></div>
      <div><b>BC0-Team-Datenbank</b><span>gemeinsame Datenbank aller BCs, Zugang für BC3 über DBeaver (bc3_role)</span><ul><li><code>bc3.lieferungen</code>: eine Zeile je echter Lieferung, mit paket_id und anfrage_id</li><li>im Testlauf nichts</li></ul></div>
      <div><b>GitHub</b><span>Team-Repo coe-factory</span><a class="ort-link" href="https://github.com/pg-coe-kmu/coe-factory/tree/main/contracts/bc3-to-bc4" target="_blank" rel="noopener">Lieferungen an BC4 ↗</a><ul><li>Lieferung an BC4 unter <code>contracts/bc3-to-bc4</code></li><li>nur nach Freigabe im Modus echt</li></ul></div>
      <div><b>Google Drive</b><span>Ablage zur Ansicht</span><a class="ort-link" href="https://drive.google.com/drive/folders/__DRIVE_ORDNER_VORSCHAU__" target="_blank" rel="noopener">Ordner _vorschau ↗</a><a class="ort-link" id="drive-lauf" href="#" target="_blank" rel="noopener" hidden>Ordner dieses Laufs ↗</a><ul><li>alle Dateien je Lieferung unter <code>_vorschau</code></li><li>auch im Testlauf</li></ul></div>
    </div>
  </section>

  <section class="voll vergleiche" id="vergleiche">
    <h2>Gleiches Konzept, mehrere Läufe</h2>
    <p class="erkl">Dasselbe simulierte Konzept, mehrfach durch BC3. Gleich bleiben sollen die Schritte und das Urteil (Ampel), der Wortlaut der Stories darf schwanken.</p>
    <table><thead><tr><th>Lauf</th><th>Datum</th><th>bis Gate 2</th><th>Epics</th><th>Stories</th><th>Ampel</th></tr></thead><tbody id="vergleich-zeilen"></tbody></table>
  </section>
</main>
<div class="druckkopf" id="druckkopf"></div>

<template id="bsp-stories">
  <div class="beispiel">
    <div class="kopf">So sieht das Ergebnis aus · Beispiel aus der Generalprobe</div>
    <div class="titel">Unvollständige Anfragen mit strukturierter Rückfrage behandeln</div>
    <div class="ak"><b>Given</b> eine Anfrage ohne Reisedatum oder Reiseziel, <b>When</b> sie verarbeitet wird, <b>Then</b> geht eine Rückfrage an die anfragende Person mit der genauen Benennung der fehlenden Felder und der Vorgang bleibt offen.</div>
    <div class="fuss">Eine von 12 Stories · Messverfahren: Statusfeld im Vorgang, Stichprobe von 50 Vorgängen</div>
  </div>
</template>
<template id="bsp-recht">
  <div class="beispiel">
    <div class="kopf">So sieht das Ergebnis aus · Beispiel aus der Generalprobe</div>
    <div class="ampel"><i></i><span>Ampel grün · KI-Verordnung: <b>begrenztes Risiko</b></span></div>
    <div class="pflicht"><span class="tag">DSGVO Art. 22</span>Buchen oder stornieren entscheidet am Ende ein Mensch.<span class="an">an BC4 · wird Story</span></div>
    <div class="pflicht"><span class="tag">KI-VO Art. 4</span>Wer das System nutzt, braucht KI-Kompetenz.<span class="an org">an die Organisation</span></div>
  </div>
</template>

<script>
// Stationen; t = Sekunde, zu der der Schritt in der Generalprobe 2617 fertig war; probe = Ergebnis dort
const ST = [
  { nr: 'BC3-00', key: 'start', orch: true, wf: 'Mi0FNs8k9wCMgHQu', datei: 'bc3-00-orchestrator', name: 'Lauf starten', art: 'regel', t: 0.2, satz: 'Der Orchestrator BC3-00 startet den Lauf. Im Betrieb sucht BC3-01 alle 15 Minuten nach neuen Lieferungen von BC2, in der Demo startet der Knopf auf dieser Seite.', erledigt: 'Lauf angelegt, Start in laeufe', probe: 'Lauf angelegt, Modus test' },
