  "Gate 2": { haupt: [{"name": "Seite aufgerufen", "art": "regel", "text": "Der Link aus der Telegram-Nachricht öffnet die Gate-2-Seite (BC3-81)."}, {"name": "Anfrage prüfen", "art": "regel", "text": "Holt Laufnummer und Schlüssel aus dem Link."}, {"name": "Ansicht holen", "art": "regel", "text": "Liest die Daten des Laufs aus der BC3-Datenbank (Tabelle gate2_ansicht)."}, {"name": "Zugang und Eingaben prüfen", "art": "regel", "text": "Prüft Schlüssel, Frist (7 Tage) und ob schon entschieden ist, beim Absenden auch die Pflichtfelder."}, {"name": "Wie weiter?", "art": "weiche", "text": "Seite zeigen, Entscheidung annehmen oder Fehler melden."}, {"name": "Seite bauen", "art": "regel", "text": "Setzt die Daten des Laufs in die Seite ein: Lieferschein, Prüfpunkte, Stichprobe, Entscheidung."}, {"neben": "beim Absenden der Entscheidung", "schritte": [{"name": "Entscheidung vermerken", "art": "regel", "text": "Hält die Entscheidung fest, damit niemand zweimal entscheidet."}, {"name": "Lauf wecken", "art": "regel", "text": "Weckt den wartenden Lauf in BC3-00, der dann BC3-80 aufruft."}]}] },
  "BC3-80": { haupt: [{"name": "Entscheidung auswerten", "art": "regel", "text": "Wertet die Entscheidung aus: freigeben, nachbessern oder ablehnen. Offene Prüfpunkte werden vermerkt, nicht verhindert."}, {"name": "In freigaben schreiben", "art": "regel", "text": "Schreibt die Entscheidung in die BC3-Datenbank (Tabelle freigaben). Von dort liest diese Seite."}, {"name": "Freigegeben?", "art": "weiche", "text": "Nur eine Freigabe im Modus echt führt weiter zu GitHub."}, {"neben": "nur bei Freigabe im Modus echt", "schritte": [{"name": "Lieferung ins Repo vorbereiten", "art": "regel", "text": "Ein Ordner je Lieferung unter contracts/bc3-to-bc4."}, {"name": "Commit und Zweig anlegen", "art": "regel", "text": "Ein Commit mit allen Dateien auf einem eigenen Zweig, nie direkt auf main."}, {"name": "Pull Request öffnen und mergen", "art": "regel", "text": "BC3 führt selbst zusammen, BC4 holt die Lieferung aus main."}]}, {"name": "Gate 2 abschliessen", "art": "regel", "text": "Gibt den Umschlag an BC3-00 zurück. Im Modus test endet es hier, ohne Pull Request."}, {"name": "Modus echt?", "art": "weiche", "text": "Nur echte Lieferungen kommen in die BC0-Team-Datenbank."}, {"neben": "nur im Modus echt", "schritte": [{"name": "In bc3.lieferungen schreiben", "art": "regel", "text": "Eine Zeile mit paket_id und anfrage_id in der BC0-Team-Datenbank."}]}, {"name": "Ergebnis zurückgeben", "art": "regel", "text": "Gibt BC3-00 den Umschlag mit allen Befunden zurück."}] },
  "BC3-10": { haupt: [{"name": "Datei holen (BC3-11)", "art": "regel", "text": "Holt das Konzept von BC2 aus GitHub (Team-Repo, main)."}, {"name": "Potenziale auslesen", "art": "regel", "text": "Ein Eintrag je Potenzial, liest die Vertragsfassungen v1 bis v3.1 und repariert kaputte Anführungszeichen."}, {"name": "Priorisierung holen", "art": "regel", "text": "Holt prozesspriorisierung.json aus demselben Ordner. Fehlt sie, läuft BC3-10 weiter."}, {"name": "Freigegebene auswählen", "art": "regel", "text": "Nur Potenziale, die BC2 an Gate 1 freigegeben hat, dazu die Kennungen der Kette (paket_id, anfrage_id)."}, {"name": "Eingang prüfen", "art": "regel", "text": "Prüft den Eingang, bevor ein Sprachmodell Geld kostet: harte Fehler brechen ab, kleinere Lücken laufen als Befund mit."}, {"name": "Umschlag füllen", "art": "regel", "text": "Alles in den Umschlag, mit dem die weiteren Schritte arbeiten. Reihenfolge nach der Empfehlung von BC2."}, {"name": "Laufprotokoll", "art": "regel", "text": "Schreibt den Stand in die BC3-Datenbank (Tabelle laeufe, BC3-91). Von dort liest diese Seite. Scheitert es, läuft der Lauf weiter."}] },
