  "BC3-30": { haupt: [{"name": "Epics auspacken", "art": "regel", "text": "Ein Eintrag je Epic, mit demselben Kontext."}, {"name": "Modus setzen", "art": "regel", "text": "Baut den Auftrag an die KI aus Risiken, Schmerzpunkten und Epics. Hat R2 gegriffen, nennt er den Bereich aus Anhang III."}, {"name": "Compliance-Agent", "art": "ki", "text": "Mistral Large: bestimmt Ampel und Risikoklasse nach der KI-Verordnung, ordnet jede Pflicht einem Adressaten zu und schlägt Zusatz-Stories vor."}, {"name": "Umschlag ergänzen", "art": "regel", "text": "Fügt die Antworten zusammen. Bei mehreren gilt der strengste Wert: rot vor gelb, hoch vor begrenzt. Eine unlesbare Antwort wird vermerkt."}, {"name": "Einstufung gegenprüfen", "art": "regel", "text": "Gegenprobe nach festen Regeln: Gibt es die Fundstelle, passt „hoch“ zu Regel R2? Herabgesetzt wird nie."}, {"name": "Laufprotokoll", "art": "regel", "text": "Schreibt den Stand in die BC3-Datenbank (Tabelle laeufe, BC3-91). Von dort liest diese Seite. Scheitert es, läuft der Lauf weiter."}] },
  "BC3-40": { haupt: [{"name": "Umschlag auspacken", "art": "regel", "text": "Holt die Epics aus BC3-20."}, {"name": "Compliance bereitstellen", "art": "regel", "text": "Holt den Befund aus BC3-30."}, {"name": "Tickets und Audit bauen", "art": "regel", "text": "Erzeugt ticket_set.json (Vertrag mit BC4) und compliance-audit.json und vergibt die Kennungen."}, {"name": "Compliance-Befund prüfen", "art": "regel", "text": "Ohne lesbaren Befund keine Lieferung: Einstufung und Pflichten dürfen nicht still fehlen."}, {"name": "Lieferung prüfen", "art": "regel", "text": "Prüft das Ticket-Set Feld für Feld gegen den Vertrag mit BC4 (Schema 3.5). Passt etwas nicht, bricht der Lauf ab."}, {"name": "Umschlag ergänzen", "art": "regel", "text": "Lieferkennung und Kurzname in den Umschlag, daran hängen Ordner und Dateinamen."}, {"name": "Laufprotokoll", "art": "regel", "text": "Schreibt den Stand in die BC3-Datenbank (Tabelle laeufe, BC3-91). Von dort liest diese Seite. Scheitert es, läuft der Lauf weiter."}] },
