  "vor-gate2": { haupt: [{"name": "Gate 2 vorbereiten", "art": "regel", "text": "Stellt die Prüfpunkte für die Entscheidung zusammen. Hochrisiko wird an drei Merkmalen festgemacht, nicht an einem einzelnen Wortfund."}, {"name": "Abdeckung anhängen", "art": "regel", "text": "Je Anforderung und Kriterium von BC2 die Story, die es abdeckt, für den Blick an Gate 2."}, {"name": "Gate-2-Daten bauen", "art": "regel", "text": "Baut die Daten der Gate-2-Seite und die Adresse, über die der Lauf später geweckt wird."}, {"name": "Gate-2-Daten speichern", "art": "regel", "text": "Speichert sie in der BC3-Datenbank (Tabelle gate2_ansicht), mit einem Schlüssel für den Link."}, {"name": "Telegram an Gate 2", "art": "regel", "text": "Schickt den Link zur Gate-2-Seite an Legal, ohne Inhalte, nur Kennungen und Zahlen."}, {"name": "Auf Freigabe warten", "art": "regel", "text": "Der Lauf hält an, bis jemand auf der Gate-2-Seite entscheidet, höchstens 7 Tage."}] },
