function aufbauHtml(s) {
  // Workflow in n8n (Anmeldung nötig) und derselbe Workflow als Export in GitHub (öffentlich), dazu Konzept bzw. Lieferordner
  const links = [['Workflow in n8n', N8N + 'workflow/' + s.wf],
                 ['Workflow in GitHub', REPO + 'blob/main/bc3-engineering-architect/workflows/' + s.datei + '.json'], ...(LINKS[s.key || s.nr] || [])];
  const linkHtml = `<div class="links">${links.map(([t, u]) => `<a href="${u}" target="_blank" rel="noopener">${t} ↗</a>`).join('')}</div>`;
  const a = AUFBAU[s.key || s.nr];
  if (!a) return linkHtml;
  const li = b => `<li class="${b.art}"><b>${b.name}</b><span class="art">${ART_TEXT[b.art]}</span><br>${b.text}</li>`;
  const teile = a.haupt.map(b => b.neben
    ? `</ol><div class="neben"><div class="titel">${b.neben}</div><ol>${b.schritte.map(li).join('')}</ol></div><ol style="counter-reset:none">`
    : li(b)).join('');
  return `<div class="aufbau"><div class="kopf">So ist der Workflow gebaut</div><ol>${teile}</ol></div>${linkHtml}`;
}
const MARKE = { ki: 'KI', ratgeber: 'Ratgeber', mensch: 'Mensch' };
const PROBE = { sek: 81.9, epics: 2, stories: 14 };
