const zeilen = [...document.querySelectorAll('.st')];

// Zustand des Laufs
const lauf = { fertig: 0, gate: false, entscheidung: null, seitFertig: 0, zeiten: [], ergebnis: [], letzteAktiv: -1 };
let gewaehlt = null;   // Station, die von Hand aufgeklappt ist (null = die Seite folgt dem Lauf, ZU = alles zugeklappt)
const ZU = -2;

function zeig(sek) {
  $('uhr').textContent = uhr(sek);
  const e = lauf.entscheidung;
  const aktiv = e ? -1 : lauf.gate ? GATE : Math.min(lauf.fertig, GATE);
  zeilen.forEach((z, i) => {
    const fertig = i < lauf.fertig || (e && i <= ABSCHLUSS);
    const nein = e && e.klasse !== 'ja' && (i === GATE || i === UEBERGABE);
    z.classList.toggle('fertig', !!fertig && !nein);
    z.classList.toggle('nein', !!nein);
    z.classList.toggle('aktiv', i === aktiv && !lauf.gate);
    z.classList.toggle('wartet', i === aktiv && lauf.gate);
    z.classList.toggle('aus', i >= UEBERGABE && !e);
    z.classList.toggle('klickbar', !!fertig || i === aktiv);
    z.classList.toggle('offen', gewaehlt === null ? i === aktiv : gewaehlt === i);
    const rechts = z.querySelector('.rechts');
    rechts.textContent = lauf.zeiten[i] !== undefined ? uhr(lauf.zeiten[i]) : rechts.dataset.dauer;
    z.querySelector('.erg').textContent = lauf.ergebnis[i] || '';
    if (i === aktiv && !lauf.gate && ST[i].t !== null) {
      // Balken nach der erwarteten Dauer aus der Generalprobe, höchstens 95 %, bis der Schritt fertig gemeldet ist
      const von = i ? ST[i - 1].t : 0;
      z.querySelector('.balken i').style.width = Math.min(95, 100 * (sek - lauf.seitFertig) / Math.max(1, ST[i].t - von)) + '%';
    }
  });
  // Die Seite folgt dem laufenden Schritt, solange niemand selbst etwas aufgeklappt hat
  if (gewaehlt === ZU && aktiv !== lauf.letzteAktiv) gewaehlt = null;
  if (gewaehlt === null && aktiv !== lauf.letzteAktiv && aktiv >= 0) {
    lauf.letzteAktiv = aktiv;
    if (aktiv > 0) zeilen[aktiv].scrollIntoView({ block: 'center' });
  }
}

function fertigMelden(bis, sek, ergebnisVon) {
  for (let k = lauf.fertig; k < bis; k++) { lauf.zeiten[k] = sek; lauf.ergebnis[k] = ergebnisVon(k); }
  if (bis > lauf.fertig) { lauf.fertig = bis; lauf.seitFertig = sek; }
}

zeilen.forEach((z, i) => {
  z.querySelector('.zeile').onclick = () => { if (z.classList.contains('klickbar')) { gewaehlt = gewaehlt === i ? null : i; zeig(+$('uhr').dataset.sek || 0); } };
  // zuklappen: nichts offen, bis der nächste Schritt beginnt (ZU), dann folgt die Seite wieder dem Lauf
  z.querySelector('.zu').onclick = ev => { ev.stopPropagation(); gewaehlt = ZU; zeig(+$('uhr').dataset.sek || 0); };
});

function kennzeichen(text, klasse = '') { const a = $('art'); a.textContent = text; a.className = 'art ' + klasse; }

function zahlen(epics, stories) {
  if (epics) $('z-epics').textContent = epics;
  if (stories) $('z-stories').textContent = stories;
}

function gateErreicht({ sek, epics, stories, gateUrl, aufzeichnung }) {
  lauf.gate = true;
  fertigMelden(GATE, sek, k => lauf.ergebnis[k] || ST[k].erledigt);
  lauf.zeiten[GATE] = sek; lauf.ergebnis[GATE] = 'wartet auf die Entscheidung';
  lauf.zeiten[VORBEREITEN] = sek; lauf.ergebnis[VORBEREITEN] = ST[VORBEREITEN].erledigt;
  zahlen(epics, stories);
  $('uhr-unter').textContent = 'bis Gate 2';
  $('pdf').classList.add('an');
  $('vergleich').textContent = aufzeichnung
    ? 'Aufzeichnung der Generalprobe vom 23.10. (Lauf bc3-2617).'
    : MODUS === 'echt' ? '' : `Generalprobe am 23.10.: ${uhr(PROBE.sek)} bis Gate 2, ${PROBE.epics} Epics, ${PROBE.stories} Stories.`;
  if (gateUrl) { $('gate').href = gateUrl; $('gate').setAttribute('aria-disabled', 'false'); $('gate').textContent = 'Gate-2-Seite öffnen und entscheiden'; }
  else $('gate').textContent = aufzeichnung ? 'Gate-2-Seite nur bei einem echten Lauf' : 'Gate-2-Seite: Telegram-Link nutzen';
  zeig(sek);
}

function entschieden({ entscheidung, person, begruendung, entschieden_am }) {
  const e = ENTSCHEIDUNG[entscheidung] || { wort: entscheidung, klasse: 'nach', bc380: 'nichts geht an BC4' };
  lauf.entscheidung = e;
  const wer = [person ? `von ${esc(person)}` : '', entschieden_am ? `um ${uhrzeit(entschieden_am)}` : ''].filter(Boolean).join(' ');
  lauf.ergebnis[GATE] = `${e.wort}${wer ? ' ' + wer : ''}${begruendung ? ' · „' + begruendung + '“' : ''}`;
  lauf.ergebnis[UEBERGABE] = MODUS === 'echt' && entscheidung === 'freigegeben' ? 'Freigegeben: geht an BC4.' : e.bc380;
  lauf.ergebnis[ABSCHLUSS] = ST[ABSCHLUSS].erledigt;
