// Idee 1: Ergebnis aus diesem Lauf (aus gate2_ansicht, sobald der Lauf an Gate 2 ist) statt Beispiel aus der Generalprobe
const AMPEL = { green: ['grün', '#2E9E5B'], yellow: ['gelb', '#E3B12D'], red: ['rot', '#B3412F'] };
const KLASSE = { minimal: 'minimales Risiko', limited: 'begrenztes Risiko', high: 'hohes Risiko', prohibited: 'verbotene Praxis' };
const ADRESSAT = { bc4: 'an BC4', organisation: 'an die Organisation', plattform: 'an die Plattform', bc2: 'an BC2', bc3: 'an BC3' };
function zeigeErgebnis(e) {
  if (!e || zeigeErgebnis.fertig) return;
