      + `<ul>${p.slice(0, 4).map(x => `<li><b>${esc(x.tag.replace(/[\[\]]/g, ''))}</b> ${esc(x.text)} <i>(${esc(ADRESSAT[x.adressat] || x.adressat)})</i></li>`).join('')}</ul>`
      + (p.length > 4 ? `<div class="fuss">und ${p.length - 4} weitere Pflichten</div>` : '');
    re.classList.add('an');
  }
  const op = box('offen');
  if (op && e.offene_punkte) {
    const n = e.offene_punkte.nach_adressat || {};
    op.innerHTML = `<div class="kopf">Aus diesem Lauf</div>${e.offene_punkte.anzahl} offene Punkte: `
      + Object.entries(n).map(([a, k]) => `${k} ${esc(ADRESSAT[a] || 'an ' + a)}`).join(', ')
      + (e.pruefung ? `<div class="fuss">Prüfung gegen den Vertrag mit BC4: ${esc(e.pruefung)}</div>` : '')
      + (e.ablage && e.ablage.ordner_link ? `<div class="fuss"><a href="${esc(e.ablage.ordner_link)}" target="_blank" rel="noopener">Ordner dieses Laufs in Google Drive ↗</a>`
         + (e.ablage.dateien || []).map(f => ` · <a href="${esc(f.link)}" target="_blank" rel="noopener">${esc(f.name)}</a>`).join('') + '</div>' : '');
