    const [wort, farbe] = AMPEL[v.ampel] || [v.ampel || '–', '#6B7280'];
    const datum = v.gestartet_am ? new Date(v.gestartet_am).toLocaleString('de-DE', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }) : '';
    return `<tr class="${v.lauf_id === dieser ? 'dieser' : ''}"><td>${esc(v.lauf_id)}${v.lauf_id === dieser ? ' (dieser)' : ''}</td><td>${datum}</td>`
      + `<td>${v.sek != null ? uhr(v.sek) : '–'}</td><td>${v.epics ?? '–'}</td><td>${v.stories ?? '–'}</td>`
      + `<td><span class="punkt" style="background:${farbe}"></span>${esc(wort)}</td></tr>`;
  }).join('');
  $('vergleiche').classList.add('an');
}

// Idee 3: Fachbegriffe mit kurzer Erklärung beim Darüberfahren (jeweils das erste Vorkommen je Absatz)
const BEGRIFFE = [
  ['Akzeptanzkriterien', 'Prüfbare Bedingung, wann eine Story erfüllt ist, hier als Given/When/Then mit Messverfahren.'],
  ['Akzeptanzkriterium', 'Prüfbare Bedingung, wann eine Story erfüllt ist, hier als Given/When/Then mit Messverfahren.'],
  ['User Stories', 'Kleine, umsetzbare Aufgaben aus Sicht der Nutzenden. Daraus baut BC4.'],
  ['Stories', 'Kleine, umsetzbare Aufgaben aus Sicht der Nutzenden. Daraus baut BC4.'],
  ['Epic', 'Ein größerer Arbeitsblock, der mehrere Stories bündelt. Hier: ein Epic je Potenzial.'],
  ['Potenzial', 'Eine Automatisierungsidee aus dem Konzept von BC2, an Gate 1 freigegeben.'],
  ['Gate 2', 'Die Stelle, an der ein Mensch die Tickets freigibt, zurückgibt oder ablehnt, bevor etwas an BC4 geht (Art. 14 KI-Verordnung).'],
  ['KI-Verordnung', 'EU AI Act (Verordnung (EU) 2024/1689): teilt KI-Systeme nach Risiko ein und knüpft Pflichten daran.'],
  ['DSGVO', 'Datenschutz-Grundverordnung: Regeln für die Verarbeitung personenbezogener Daten.'],
  ['Pull Request', 'Vorschlag einer Änderung im GitHub-Repository. So liefert BC3 nach der Freigabe an BC4.'],
  ['Temperatur 0', 'Das Modell wählt immer die wahrscheinlichste Antwort, damit Läufe möglichst gleich ausfallen.'],
  ['fester Seed', 'Fester Startwert für den Zufall im Modell, damit Läufe nachvollziehbar bleiben.'],
  ['JSON', 'Maschinenlesbares Datenformat. Die KI muss so antworten, damit feste Regeln das Ergebnis prüfen können.'],
  ['Adressat', 'Wer eine Pflicht erfüllen muss: BC4 baut sie, die Organisation regelt sie, oder BC2 muss nachliefern.'],
];
function begriffeMarkieren(wurzel) {
  wurzel.querySelectorAll('.satz, .aufbau li, .vorher li').forEach(el => {
    const genutzt = new Set();
    for (const [wort, erkl] of BEGRIFFE) {
      if ([...genutzt].some(g => g.includes(wort) || wort.includes(g))) continue;
      const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
      let n;
      while ((n = walker.nextNode())) {
        if (n.parentElement.closest('.begriff, b')) continue;
        const i = n.textContent.indexOf(wort);
        if (i < 0) continue;
        const r = document.createRange(); r.setStart(n, i); r.setEnd(n, i + wort.length);
        const span = document.createElement('span'); span.className = 'begriff'; span.tabIndex = 0; span.dataset.erkl = erkl;
        r.surroundContents(span); genutzt.add(wort); break;
      }
    }
  });
}
begriffeMarkieren(document);

