// Anfragen an n8n; lokal mit ?probe= durch Probedaten ersetzt
async function anfrage(methode, query = '') {
  if (!LIVE && PROBE_MODUS) return probeAntwort(methode);
  const ziel = methode === 'POST' ? '__PFAD_LIVE_START__' : '__PFAD_LIVE_STAND__';
  const trenner = query ? '&' : '?';
  const r = await fetch(`/webhook/${ziel}${query}${trenner}k=${ZUGANG}`, { method: methode, cache: 'no-store' });
  if (!r.ok) throw new Error(`${methode === 'POST' ? 'Start' : 'Stand'}: Antwort ${r.status}${r.status === 403 ? ' (Schlüssel abgelaufen, Seite neu laden)' : ''}`);
  return r.json();
}
const probeLos = { zeit: 0 };
function probeAntwort(methode) {
  if (PROBE_MODUS === 'fehler') throw new Error('Start: Antwort 403 (Schlüssel abgelaufen, Seite neu laden)');
  if (methode === 'POST') {
    probeLos.zeit = performance.now();
    const gestartet = MODUS !== 'echt' ? undefined : PROBE_MODUS === 'leer' ? [] : ['contracts/bc2-to-bc3/lieferungen/noroai-probe-f1/konzept_KP-06.json'];
    return { ok: true, gestartet_am: new Date().toISOString(), gestartet, geprueft: 4 };
  }
  const sek = (performance.now() - probeLos.zeit) / 1000 * tempo;
  const fertig = ST.filter(s => s.t !== null && s.t <= sek).length;
  const gate = sek >= PROBE.sek, entschieden = sek >= PROBE.sek + 40;
  return { lauf_id: 'bc3-probe', status: entschieden ? 'abgelehnt' : gate ? 'wartet_gate2' : 'laeuft', letzter_schritt: fertig ? ST[fertig - 1].nr : 'BC3-00',
           anzahl_epics: fertig > STELLE('BC3-40') ? 2 : null, anzahl_stories: fertig > STELLE('BC3-40') ? 15 : null, gate2_url: gate && !entschieden ? '#probe-gate2' : null,
           entscheidung: entschieden ? 'abgelehnt' : null, person: entschieden ? 'sv' : null, begruendung: entschieden ? 'Probe' : null,
           entschieden_am: entschieden ? new Date().toISOString() : null,
           // Probedaten wie aus gate2_ansicht (Werte aus Lauf bc3-3008)
           ergebnis: gate ? { ampel: 'green', klasse: 'limited', pruefung: 'bestanden',
             epics: [{ titel: '[SIMULIERT] Reiseanfrage automatisch erfassen und Verfügbarkeit prüfen', stories: 8 }, { titel: '[SIMULIERT] Angebot erstellen und Buchung nach Freigabe auslösen', stories: 7 }],
             story: { story: 'Pflichtfelder extrahieren', text: 'Given eine Extraktion mit Konfidenz unter dem Schwellwert, When der Vorgang angelegt wird, Then wird er als prüfbedürftig markiert und einem Menschen zugewiesen.', mess: 'Statusfeld im Vorgang, Stichprobe von 50 Vorgängen (K4)' },
             pflichten: [{ tag: '[AI-Act Art. 4]', text: 'Personen, die das System nutzen, brauchen KI-Kompetenz.', adressat: 'organisation' }, { tag: '[DSGVO Art. 22]', text: 'Buchung erst nach menschlicher Freigabe.', adressat: 'bc4' }],
             offene_punkte: { anzahl: 4, nach_adressat: { bc2: 1, plattform: 1, organisation: 2 } },
             ablage: { ordner_link: '#probe-ordner', dateien: [{ name: 'ticket_set.json', link: '#probe-datei' }, { name: 'compliance-audit.json', link: '#probe-datei' }] } } : null,
           vergleich: gate ? [{ lauf_id: 'bc3-probe', gestartet_am: new Date().toISOString(), sek: 78, epics: 2, stories: 15, ampel: 'green' },
             { lauf_id: 'bc3-3008', gestartet_am: '2026-10-25T15:27:40Z', sek: 80, epics: 2, stories: 14, ampel: 'green' },
             { lauf_id: 'bc3-2617', gestartet_am: '2026-10-23T14:54:04Z', sek: 82, epics: 2, stories: 14, ampel: 'green' }] : null };
}

async function live(modus) {
  MODUS = modus;
  knoepfeAus();
  $('fehler').classList.remove('an', 'info');
  if (modus === 'echt') $('hinweis').textContent = 'Suche neue Lieferungen von BC2 …';
  let seit, gestartet = [];
  try {
    const s = await anfrage('POST', modus === 'echt' ? '?art=pruefen' : '');
    seit = s.gestartet_am;
    if (!seit) throw new Error('Start: keine Startzeit erhalten');
    if (modus === 'echt') {
      gestartet = s.gestartet || [];
      if (!gestartet.length) {
        $('fehler').innerHTML = `Keine neue Lieferung von BC2.<small>Stand ${uhrzeit(seit)}: Alle ${s.geprueft ?? ''} Konzepte im Repo sind schon bearbeitet oder noch nicht freigegeben. Den Ablauf zeigt der Testfall.</small>`;
        $('fehler').classList.add('an', 'info');
        $('hinweis').textContent = '';
        knoepfeAn();
        return;
      }
      PFAD_ECHT = gestartet[0];
    }
  } catch (e) {
    $('fehler').innerHTML = `Live-Start fehlgeschlagen. Es läuft kein Lauf.<small>${esc(e.message)}. Seite neu laden, oder „Aufzeichnung ansehen“.</small>`;
    $('fehler').classList.add('an');
    $('aufz').disabled = false;
    return;
  }
  kennzeichen(modus === 'echt' ? 'Live-Fall' : 'Testfall', 'live');
  $('grenze').textContent = modus === 'echt' ? 'Nach der Freigabe geht das Ergebnis an BC4.' : 'Testlauf: Auch nach einer Freigabe entsteht kein Pull Request an BC4.';
  $('hinweis').textContent = modus === 'echt'
    ? `Neue Lieferung gefunden: ${(PFAD_ECHT.match(/konzept_(.+)[.]json$/) || [, PFAD_ECHT])[1]}${gestartet.length > 1 ? ` und ${gestartet.length - 1} weitere` : ''}. Der Lauf startet …`
    : 'Lauf gestartet, BC3-00 übernimmt …';
  const los = performance.now();
  let fehler = 0, uhrLaeuft = true, gateWarten = 0;
  const tick = () => {
    if (!uhrLaeuft) return;
    const sek = (performance.now() - los) / 1000;
    $('uhr').dataset.sek = sek;
    zeig(sek);
    requestAnimationFrame(tick);
  };
  tick();
  const ENDE = ['freigegeben', 'abgelehnt', 'nachbessern'];
  const frage = async () => {
    const sek = (performance.now() - los) / 1000;
    try {
      const d = await anfrage('GET', '?seit=' + encodeURIComponent(seit) + (MODUS === 'echt' ? '&pfad=' + encodeURIComponent(PFAD_ECHT) : ''));
      fehler = 0;
      if (d.lauf_id && !lauf.gate) $('hinweis').textContent = `Lauf ${d.lauf_id} · ${MODUS_TEXT[MODUS]}`;
      zahlen(d.anzahl_epics, d.anzahl_stories);
      if (d.lauf_id) lauf.laufId = d.lauf_id;
      if (d.ergebnis) zeigeErgebnis(d.ergebnis);
      if (d.vergleich) zeigeVergleich(d.vergleich, d.lauf_id);
      if (!lauf.gate) {
        const bis = ST.findIndex(s => !s.orch && s.nr === d.letzter_schritt) + 1;
        fertigMelden(Math.min(Math.max(bis, d.lauf_id ? 1 : 0), GATE), sek, k => k === STELLE('BC3-40') && d.anzahl_stories ? `${d.anzahl_stories} Stories, gegen den Vertrag geprüft` : ST[k].erledigt);
      }
      if (d.status === 'wartet_gate2' && !lauf.gate) {
        // BC3-91 meldet Gate 2 kurz bevor der Schlüssel gespeichert ist: bis zu dreimal nachfragen
        if (!d.gate2_url && ++gateWarten <= 3) return setTimeout(frage, 1500);
        uhrLaeuft = false;
        gateErreicht({ sek, epics: d.anzahl_epics, stories: d.anzahl_stories, gateUrl: d.gate2_url });
        $('hinweis').textContent = `Lauf ${d.lauf_id} wartet an Gate 2 · die Seite zeigt die Entscheidung, sobald sie fällt`;
      }
      if (ENDE.includes(d.status) && d.entscheidung) {
        if (!lauf.gate) { uhrLaeuft = false; gateErreicht({ sek, epics: d.anzahl_epics, stories: d.anzahl_stories }); }
        return entschieden(d);
      }
      if (d.status === 'abgebrochen') {
        uhrLaeuft = false;
        $('fehler').innerHTML = `Lauf ${esc(d.lauf_id)} abgebrochen in ${esc(d.letzter_schritt || '?')}.<small>Den Grund zeigt die Übersicht BC3-82.</small>`;
        $('fehler').classList.add('an');
        return;
      }
    } catch (e) {
      if (++fehler >= 3) {
        uhrLaeuft = false;
        $('fehler').innerHTML = `Stand nicht erreichbar.<small>${esc(e.message)}. Der Lauf läuft trotzdem weiter, die Übersicht und Telegram zeigen ihn.</small>`;
        $('fehler').classList.add('an');
        return;
      }
    }
    // vor Gate 2 alle 2 Sekunden, danach alle 3 Sekunden bis zur Entscheidung
    setTimeout(frage, lauf.gate ? 3000 : 2000);
  };
  frage();
}

function startbar() {
  if (!LIVE && !PROBE_MODUS) {
    $('fehler').innerHTML = 'Hier ist kein Live-Start möglich.<small>Die Seite ist nicht über n8n geöffnet oder ohne Schlüssel. Seite über die Übersicht öffnen, oder „Aufzeichnung ansehen“.</small>';
    $('fehler').classList.add('an');
    return false;
  }
  return true;
}
$('pruefen').onclick = () => { if (startbar()) live('echt'); };
$('los').onclick = () => { if (startbar()) live('test'); };
$('aufz').onclick = () => { $('fehler').classList.remove('an', 'info'); aufzeichnung(); };

